import WebSocket from 'ws';
import http from 'http';
import crypto from 'crypto';
import { EventEmitter } from 'events';

interface ContainerSession {
  id: string;
  userId: string;
  token: string;
  ws?: WebSocket;
  lastHeartbeat: number;
  state: 'pending' | 'active' | 'draining';
}

class SessionRegistry {
  private sessions = new Map<string, ContainerSession>();
  private tokenIndex = new Map<string, string>();

  register(session: ContainerSession): void {
    this.sessions.set(session.id, session);
    this.tokenIndex.set(session.token, session.id);
  }

  findByToken(token: string): ContainerSession | undefined {
    const id = this.tokenIndex.get(token);
    return id ? this.sessions.get(id) : undefined;
  }

  findById(id: string): ContainerSession | undefined {
    return this.sessions.get(id);
  }

  remove(id: string): void {
    const session = this.sessions.get(id);
    if (session) {
      this.tokenIndex.delete(session.token);
      this.sessions.delete(id);
    }
  }
}

class OrchestratorGateway extends EventEmitter {
  private server: http.Server;
  private wss: WebSocket.Server;
  private registry: SessionRegistry;
  private pendingUpgrades = new Map<string, { resolve: Function; timer: NodeJS.Timeout }>();

  constructor(port: number) {
    super();
    this.registry = new SessionRegistry();
    this.server = http.createServer(this.handleHttp.bind(this));
    this.wss = new WebSocket.Server({ noServer: true });
    this.server.on('upgrade', this.handleUpgrade.bind(this));
    this.server.listen(port);
  }

  private handleHttp(req: http.IncomingMessage, res: http.ServerResponse): void {
    if (req.method === 'POST' && req.url === '/api/sessions') {
      this.handleCreateSession(req, res);
    } else {
      res.writeHead(404).end();
    }
  }

  private async handleCreateSession(req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
    const authHeader = req.headers['authorization'];
    if (!authHeader || !this.validateBearerToken(authHeader)) {
      res.writeHead(401).end();
      return;
    }

    const userId = this.extractUserId(authHeader);
    const sessionId = crypto.randomUUID();
    const upgradeToken = crypto.randomBytes(32).toString('hex');

    const session: ContainerSession = {
      id: sessionId,
      userId,
      token: upgradeToken,
      lastHeartbeat: Date.now(),
      state: 'pending'
    };

    this.registry.register(session);

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ sessionId, upgradeToken }));
  }

  private async handleUpgrade(req: http.IncomingMessage, socket: any, head: Buffer): Promise<void> {
    const url = new URL(req.url!, `http://${req.headers.host}`);
    const sessionId = url.searchParams.get('session');
    const token = url.searchParams.get('token');

    if (!sessionId || !token) {
      socket.destroy();
      return;
    }

    const session = this.registry.findById(sessionId);
    if (!session) {
      socket.destroy();
      return;
    }

    // Validate the upgrade token matches the session
    const isValid = await this.verifyUpgradeToken(session, token);

    if (!isValid) {
      socket.destroy();
      return;
    }

    this.wss.handleUpgrade(req, socket, head, (ws) => {
      this.onConnection(ws, session);
    });
  }

  private async verifyUpgradeToken(session: ContainerSession, providedToken: string): Promise<boolean> {
    // Simulate async token verification (e.g., checking revocation list)
    await this.checkTokenRevocationList(providedToken);

    // Timing-safe comparison
    const expected = Buffer.from(session.token, 'hex');
    const provided = Buffer.from(providedToken, 'hex');

    if (expected.length !== provided.length) {
      return false;
    }

    return crypto.timingSafeEqual(expected, provided);
  }

  private async checkTokenRevocationList(token: string): Promise<void> {
    // Simulates async I/O to check if token was revoked
    return new Promise(resolve => setTimeout(resolve, 10));
  }

  private onConnection(ws: WebSocket, session: ContainerSession): void {
    session.ws = ws;
    session.state = 'active';

    ws.on('message', (data) => this.handleMessage(session, data));
    ws.on('close', () => this.handleDisconnect(session));
    ws.on('pong', () => { session.lastHeartbeat = Date.now(); });
  }

  private async handleMessage(session: ContainerSession, data: WebSocket.Data): Promise<void> {
    try {
      const msg = JSON.parse(data.toString());
      if (msg.type === 'exec') {
        await this.executeInContainer(session, msg.payload);
      }
    } catch (e) {
      session.ws?.send(JSON.stringify({ error: 'invalid message' }));
    }
  }

  private async executeInContainer(session: ContainerSession, payload: any): Promise<void> {
    // Container execution logic
    this.emit('exec', { userId: session.userId, command: payload.command });
  }

  private handleDisconnect(session: ContainerSession): void {
    session.state = 'draining';
    this.registry.remove(session.id);
  }

  private validateBearerToken(header: string): boolean {
    return header.startsWith('Bearer ') && header.length > 7;
  }

  private extractUserId(header: string): string {
    // In production, decode JWT; simplified here
    return crypto.createHash('sha256').update(header).digest('hex').slice(0, 16);
  }
}

export { OrchestratorGateway, SessionRegistry };
